65	
66	// The secret-free detection snapshot stored under Migration.items.scan. Used here
67	// only to log standalone containers and derive fallbacks; every field is
68	// re-validated before it can flow into a command.
69	export type ScanSnapshot = {
70	  engines?: { engine?: string; present?: boolean }[];
71	  // Exact engine variant + version detected on the source (read-only). Chooses the
72	  // MATCHING engine package on the target; the variant is a validated enum, never
73	  // interpolated into a command.
74	  dbEngines?: { engine?: string; variant?: string | null; version?: string | null }[];
75	  containers?: { name?: string; image?: string; ports?: string; mounts?: string[] }[];
76	  ports?: { port?: number; proc?: string; role?: string }[];
77	  services?: { name?: string }[];
78	  appDirs?: { path?: string; runtime?: string; signature?: string }[];
79	};
80	
81	type Items = {
82	  paths?: string[];
83	  // Legacy per-DB list (with encrypted password) — no longer used for dumping;
84	  // kept optional so old rows still type-check. Passwordless dumping uses dbEngines.
85	  databases?: { engine: string; name: string; user: string; passEnc?: string }[];
86	  dbEngines?: string[]; // which engines to dump via source root LOCAL auth
87	  dockerVolumes?: string[]; // named docker volumes to copy (/var/lib/docker/volumes/<n>/_data)
88	  composeDirs?: string[]; // compose project dirs → `docker compose up -d`
89	  verifyPorts?: number[]; // ports that should be listening on the target after bring-up
90	  hasContainers?: boolean; // Docker containers detected → install Docker Engine + compose
91	  webServers?: string[]; // "nginx" | "apache" to install + enable vhosts for
92	  runtimes?: string[]; // "nodejs" | "python3" to install
93	  totalBytes?: number; // trusted server-side total to migrate (bytes) for the pre-flight
94	  /**
95	   * EXPLICIT customer consent to put Docker's stores on an attached block-storage
96	   * volume. Default (absent/false) means the volume is left completely alone:
97	   * volumes are portable add-on storage and mounting a system path on one makes
98	   * it undetachable, so the engine fails the pre-flight with an honest message
99	   * rather than take the volume on its own. Carried through Migration.items (an
100	   * existing Json column) — no schema change.
101	   */
102	  useVolumeForDocker?: boolean;
103	  scan?: ScanSnapshot;
104	};
105	
106	// A single line item in the honest final summary.
107	export type MigrationStepResult = {
108	  step: string;
109	  // running  = verified running on the target
110	  // copied   = placed on the target but NOT verified running (may need a manual step)
111	  // failed   = attempted, failed (reason in detail) — did NOT fail the migration
112	  // skipped  = nothing to do
113	  status: "running" | "copied" | "failed" | "skipped";
114	  detail: string;
115	};
116	
117	/**
118	 * A named thing that is NOT finished, with why and the exact command that
119	 * finishes it. Shared shape for TLS gaps and for the blocking problems the
120	 * systemd pre-flight / health gate find, so the summary reads the same way
121	 * whatever produced the entry.
122	 */
123	export type PendingItem = { domain: string; why: string; fix: string };
124	
125	/**
126	 * The terminal outcome of a real run, as judged by this engine.
127	 *
128	 *   COMPLETED             — every domain the SOURCE served is serving here, and
129	 *                           every migrated unit is healthy.
130	 *   COMPLETED_WITH_ISSUES — the move finished but at least one source domain is
131	 *                           dark, or a migrated service is crash-looping. The
132	 *                           customer MUST see this as "not done yet".
133	 *
134	 * Introduced after a real run on 2026-07-25 logged `Sites actually serving: 4/4`
135	 * while six of the customer's domains were dark and `nexis-next.service` had
136	 * crash-looped 78 times. A run that cannot fail is not a check.
137	 */
138	export type MigrationOutcome = "COMPLETED" | "COMPLETED_WITH_ISSUES";
139	
140	export type RealMigrationSummary = {
141	  results: MigrationStepResult[];
142	  verifiedRunning: string[];
143	  needsAttention: string[];
144	  /** Hostnames confirmed to have a live certificate on the new server. */
145	  tlsSecured?: string[];
146	  /** Hostnames still without TLS, each with why and the exact command to fix it. */
147	  tlsPending?: TlsPending[];
148	  /**
149	   * Hostnames HTTP-probed at the end, with the status code each returned.
150	   * `reason` is the honest explanation whenever `serving` is false — including
151	   * "answered, but with the stock Apache/nginx default page" and "the
152	   * certificate served here does not cover this name".
153	   */
154	  siteProbes?: { domain: string; http: string; https: string; serving: boolean; reason?: string }[];
155	  /**
156	   * THE DENOMINATOR. Every hostname the SOURCE server was configured to answer
157	   * on, taken from its own live vhost config — NOT the set we chose to publish.
158	   * Scoring against the generated-config set is what let the old summary report
159	   * 4/4 while six domains were dark.
160	   */
