2740	/**
2741	 * Re-validate a SiteSpec read back off the target. It is our own JSON, but it
2742	 * came off a machine, so every field goes through the same allowlists again
2743	 * before it can reach a config file or a command.
2744	 */
2745	function sanitizeSiteSpec(raw: unknown): SiteSpec | null {
2746	  const r = raw as Record<string, unknown> | null;
2747	  if (!r || typeof r !== "object") return null;
2748	  const bindIp = typeof r.bindIp === "string" && IPV4_RE.test(r.bindIp) ? r.bindIp : "";
2749	  const kind: "nginx" | "apache" = r.kind === "apache" ? "apache" : "nginx";
