2751	  for (const s of (Array.isArray(r.sites) ? r.sites : []).slice(0, 20) as Record<string, unknown>[]) {
2752	    const names = (Array.isArray(s?.names) ? (s.names as unknown[]) : [])
2753	      .map((n) => normalizeDomain(String(n ?? "")))
2754	      .filter((n): n is string => !!n)
2755	      .slice(0, 12);
2756	    if (!names.length) continue;
2757	    const portNum = Number(s?.proxyPort);
2758	    const proxyPort = Number.isInteger(portNum) && portNum >= 1 && portNum <= 65535 ? portNum : 0;
2759	    const root = typeof s?.root === "string" && validPath(s.root) ? s.root : "";
2760	    if (!proxyPort && !root) continue;
2761	    sites.push({
2762	      names,
2763	      wildcard: normalizeDomain(String(s?.wildcard ?? "")) ?? "",
2764	      proxyPort,
2765	      root,
2766	      certDomain: normalizeDomain(String(s?.certDomain ?? "")) ?? "",
2767	      phpSocket: typeof s?.phpSocket === "string" && validPath(s.phpSocket) ? s.phpSocket : "",
2768	    });
2769	  }
2770	  return sites.length ? { sites, bindIp, http2: !!r.http2, kind } : null;
