2800	/**
2801	 * Repoint migrated renewal profiles at THIS server. Without this, `certbot renew`
2802	 * keeps trying the old server's webroot (or its nginx/apache installer) and the
2803	 * migrated certificates quietly stop renewing about 60 days later. DNS-01
2804	 * profiles are left alone — their authenticator is already host-independent.
2805	 */
2806	const RENEWAL_FIX_SCRIPT = [
2807	  "n=0",
2808	  "for f in /etc/letsencrypt/renewal/*.conf; do",
2809	  '  [ -f "$f" ] || continue',
2810	  "  if grep -qE '^authenticator[[:space:]]*=[[:space:]]*dns' \"$f\"; then continue; fi",
2811	  "  sed -i -e 's|^authenticator[[:space:]]*=.*|authenticator = webroot|' " +
2812	    "-e 's|^installer[[:space:]]*=.*|installer = None|' " +
2813	    "-e 's|^webroot_path[[:space:]]*=.*|webroot_path = /var/www/html,|' \"$f\"",
2814	  "  awk 'BEGIN{m=0} /^\\[\\[webroot_map\\]\\]/{print; m=1; next} m==1 && /=/{sub(/=.*/, \"= /var/www/html\"); print; next} {print}' \"$f\" > \"$f.nx\" 2>/dev/null && mv \"$f.nx\" \"$f\"",
2815	  "  grep -q '^webroot_path' \"$f\" || printf 'webroot_path = /var/www/html,\\n' >> \"$f\"",
2816	  "  n=$((n+1))",
2817	  "done",
2818	  "printf 'RENEWALFIX %s\\n' \"$n\"",
2819	  "",
2820	].join("\n");
