2822	async function fixRenewalConfigs(conn: Client, sftp: SFTPWrapper, work: string): Promise<number> {
2823	  const p = `${work}/fix-renewal.sh`;
2824	  await sftpWrite(sftp, p, RENEWAL_FIX_SCRIPT).catch(() => {});
2825	  const r = await sh(conn, `sh ${p} 2>/dev/null`, SETUP_TIMEOUT_MS);
2826	  const m = /RENEWALFIX\s+(\d+)/.exec(r.stdout);
2827	  return m ? Number(m[1]) : 0;
