2847	/**
2848	 * DNS-01 via the customer's connected Cloudflare account — the only way to get a
2849	 * wildcard. The token never appears in argv: it is written to a 0600 credentials
2850	 * file over SFTP and shredded immediately afterwards, success or failure.
2851	 */
2852	async function issueDns01(
2853	  conn: Client,
2854	  sftp: SFTPWrapper,
2855	  work: string,
2856	  token: string,
2857	  certName: string,
2858	  domains: string[],
2859	  email: string
2860	): Promise<{ ok: boolean; err: string }> {
2861	  if (!token || token.length > 512 || /[\r\n]/.test(token)) return { ok: false, err: "unusable Cloudflare token" };
2862	  const ds = [...new Set(domains)].filter((d) => DOMAIN_RE.test(d.replace(/^\*\./, ""))).slice(0, 20);
2863	  if (!ds.length || !DOMAIN_RE.test(certName)) return { ok: false, err: "no valid hostnames" };
2864	  const ini = `${work}/cf-dns.ini`;
2865	  try {
2866	    await sftpWrite(sftp, ini, `dns_cloudflare_api_token = ${token}\n`);
2867	    await sh(conn, `chmod 600 ${ini}`);
2868	    const cmd =
2869	      `certbot certonly --dns-cloudflare --dns-cloudflare-credentials ${ini} --dns-cloudflare-propagation-seconds 45 ` +
2870	      `-n --agree-tos ${acmeAccountArgs(email)} --keep-until-expiring --cert-name ${certName} ` +
2871	      `${ds.map((d) => `-d '${d}'`).join(" ")} 2>&1`;
2872	    const r = await sh(conn, cmd, IMAGE_TIMEOUT_MS);
2873	    if (await certExists(conn, certName)) return { ok: true, err: "" };
2874	    return { ok: false, err: tailOf(r, 2, 220) };
2875	  } finally {
2876	    await sh(conn, `shred -u ${ini} 2>/dev/null || rm -f ${ini}`).catch(() => {});
2877	  }
2878	}
