2880	/**
2881	 * A wildcard covers exactly ONE label, so a multi-tenant app that also has a
2882	 * staging tier (`hq.stg.example.com`) needs `*.stg.example.com` as well as
2883	 * `*.example.com`. Return every base that needs its own wildcard.
2884	 */
2885	function wildcardBasesFor(site: TargetSite): string[] {
2886	  const bases = new Set<string>();
2887	  if (site.wildcard) bases.add(site.wildcard);
2888	  for (const n of site.names) {
2889	    const parts = n.split(".");
2890	    if (parts.length < 3) continue;
2891	    const parent = parts.slice(1).join(".");
2892	    if (site.wildcard && parent !== site.wildcard && parent.endsWith(`.${site.wildcard}`)) bases.add(parent);
2893	  }
2894	  return [...bases].slice(0, 4);
2895	}
