2945	async function secureSites(opts: {
2946	  conn: Client;
2947	  sftp: SFTPWrapper;
2948	  work: string;
2949	  spec: SiteSpec;
2950	  targetIp: string;
2951	  email: string;
2952	  cloudflareToken?: string | null;
2953	  webOwnedByContainer: boolean;
2954	  say: (line: string) => Promise<void>;
2955	}): Promise<{ secured: string[]; pending: TlsPending[] }> {
2956	  const { conn, sftp, work, spec, targetIp, email, cloudflareToken, webOwnedByContainer, say } = opts;
2957	  const secured: string[] = [];
2958	  const pending: TlsPending[] = [];
