2960	  await ensureAcmeWebroot(conn);
2961	  const fixed = await fixRenewalConfigs(conn, sftp, work);
2962	  if (fixed) await say(`  Repointed ${fixed} certificate renewal profile(s) at this server so they keep auto-renewing.`);
