2964	  let needCertbot = false;
2965	  for (const s of spec.sites) for (const n of s.names) if (!(await certExists(conn, n))) needCertbot = true;
2966	  if (needCertbot) {
2967	    const wantCf = !!cloudflareToken && spec.sites.some((s) => s.wildcard);
