2975	    let covered = false;
2976	    for (const n of site.names) {
2977	      if (await certExists(conn, n)) {
2978	        secured.push(...site.names);
2979	        await say(`  ${n}: HTTPS already covered by the certificate migrated from the old server.`);
2980	        covered = true;
2981	        break;
2982	      }
2983	    }
2984	    if (covered) continue;
