2277	  const out: UnitExecRef[] = [];
2278	  const seen = new Set<string>();
2279	  for (const line of unfoldUnitLines(text)) {
2280	    const m = /^(ExecStart|ExecStartPre|ExecStartPost)\s*=\s*(.*)$/.exec(line);
2281	    if (!m) continue;
2282	    let rhs = m[2].trim();
2283	    if (!rhs) continue; // `ExecStart=` — a list reset, not a command
2284	    rhs = rhs.replace(/^[-@+!]+\s*/, "").trim();
2285	    if (!rhs) continue;
2286	    let exe: string;
2287	    const q = rhs[0];
2288	    if (q === '"' || q === "'") {
2289	      const end = rhs.indexOf(q, 1);
2290	      exe = end > 0 ? rhs.slice(1, end) : rhs.slice(1);
2291	    } else {
2292	      exe = rhs.split(/\s+/)[0] ?? "";
2293	    }
2294	    exe = exe.trim();
2295	    if (!exe.startsWith("/")) continue; // PATH-resolved — not ours to check
2296	    if (!validPath(exe)) continue; // %-specifiers and odd charsets: unresolvable here
