2324	  const body = await sh(conn, `cat ${unitFile} 2>/dev/null`, SETUP_TIMEOUT_MS);
2325	  const refs = parseUnitExecPaths(body.stdout);
2326	  for (const ref of refs) {
2327	    if (await shOk(conn, `test -x ${ref.path}`)) continue;
2328	
2329	    // It exists but is not executable — a real 203/EXEC cause too. Reported, not
2330	    // silently chmod-ed: changing the mode of the customer's own file is their
