2368	      }
2369	    }
2370	
2371	    // 3. Refuse to guess. A unit that cannot exec is worth one loud line.
2372	    blockers.push({
2373	      domain: `${unit}.service`,
2374	      why:
2375	        `its ${ref.directive} runs ${ref.path}, which does not exist on this server and is not installed anywhere else here ` +
2376	        `(systemd fails this as 203/EXEC and restarts the service forever)`,
2377	      fix:
2378	        `install the program that provides ${base} on this server, then either symlink it — ln -s "$(command -v ${base})" ${ref.path} — ` +
2379	        `or edit ${unitFile} to the real path, and run: systemctl daemon-reload && systemctl restart ${unit}`,
