/**
 * Everything `preflightUnitExecs` needs from the target machine, as an
 * interface rather than a `Client`.
 *
 * WHY: field note #13 ("resolve ExecStart binaries") was written after a unit
 * crash-looped 880 times, was never implemented, and the SAME failure came back
 * four months later as #25 (`/usr/local/bin/node`, 78 restarts, migration
 * reported success). The fix is only a fix if it stays correct, and it can only
 * be kept correct by a test — so the one decision ladder that stands between a
 * copied unit and a permanent crash-loop is driven through this seam and
 * exercised by `test/migration-gate.test.ts` with a fake host. Nothing here is
 * mocked in production: `sshUnitExecHost` is the only implementation the engine
 * uses.
 */
export type UnitExecHost = {
  /** The unit file's text; "" when it cannot be read. */
  readUnitFile: (unitFile: string) => Promise<string>;
  /** `test -x` — present AND executable. */
  isExecutable: (path: string) => Promise<boolean>;
  /** `test -e` — present at all (a non-executable file is still a 203/EXEC cause). */
  exists: (path: string) => Promise<boolean>;
  /** `command -v <basename>` — the same program installed under a different prefix. */
  whichSameName: (basename: string) => Promise<string>;
  /** `mkdir -p <dir> && ln -s <target> <linkPath>`; true only if the link now execs. */
  symlink: (opts: { target: string; linkPath: string; dir: string }) => Promise<boolean>;
};

/** The real, SSH-backed UnitExecHost — the only one production ever uses. */
function sshUnitExecHost(conn: Client): UnitExecHost {
  return {
    readUnitFile: async (unitFile) => (await sh(conn, `cat ${unitFile} 2>/dev/null`, SETUP_TIMEOUT_MS)).stdout,
    isExecutable: (path) => shOk(conn, `test -x ${path}`),
    exists: (path) => shOk(conn, `test -e ${path}`),
    whichSameName: async (base) => clean((await sh(conn, `command -v ${base} 2>/dev/null`)).stdout, 255),
