      // `ln -s` (not -sfn): we already proved the path is absent, so a plain
      // symlink can never clobber anything. If a race created it meanwhile we
      // want the loud failure, not a silent replacement.
      const ok = await shOk(conn, `mkdir -p ${dir} && ln -s ${target} ${linkPath}`);
