  migrationId?: string;
  /**
   * `"tls"` turns this job into the POST-DNS-CUTOVER certificate pass instead of
   * a migration: it re-runs the certificate ladder against the site
   * configuration the original run persisted, and copies nothing. See
   * `runPostCutoverTls` for why that is a separate phase rather than a separate
   * JobType (prisma/schema.prisma is frozen; `MIGRATE` already exists and is
