// ---- TLS inputs: resolved HERE, on the Nxeon side --------------------------
/**
 * The three certificate inputs `runRealMigration` / `issueMigrationCertificates`
 * declare and that this caller used to drop on the floor.
 *
 * Real incident: the engine shipped a complete three-rung TLS ladder
 * (migrated certificate → DNS-01 wildcard via Cloudflare → HTTP-01 webroot) and
 * this call site passed only `{migration, target, items, report}`. The
 * consequences were invisible because every rung *degraded politely*:
 *
 *   - no `cloudflareToken`  ⇒ rung 3 could never fire, so every multi-tenant
 *     app was told "Connect Cloudflare in Settings" even when the customer had
 *     already completed the OAuth flow. A `*.domain` cert cannot be issued any
 *     other way (HTTP-01 cannot validate a wildcard), so those tenants were
 *     permanently stuck on a certificate warning.
 *   - no `acmeEmail`        ⇒ every certificate registered
 *     `--register-unsafely-without-email`, so Let's Encrypt has no address to
 *     send the 20/7/1-day expiry warnings to. That failure is silent for 60 days
 *     and then takes the site down.
 *   - no `knownDomains`     ⇒ hostnames the customer registered WITH US were
 *     excluded from the published set and from the certificate SANs.
 *
 * Everything is read from OUR database — never off the customer's box.
 * Resolution never throws: a missing/expired Cloudflare connection simply drops
 * the engine to a lower rung, exactly as it does for a customer who never
 * connected, and that is reported honestly in the run log.
 */
type MigrationTlsInputs = {
  cloudflareToken: string | null;
  acmeEmail: string | null;
  knownDomains: string[];
  /** One line for the run log, so the customer can see which rungs are available. */
  note: string;
};

async function resolveTlsInputs(userId: string): Promise<MigrationTlsInputs> {
  let cloudflareToken: string | null = null;
  let acmeEmail: string | null = null;
  const knownDomains: string[] = [];
  const notes: string[] = [];

  try {
    const user = await db.user.findUnique({
      where: { id: userId },
      select: { id: true, email: true, cloudflareTokenEnc: true },
    });
    if (user) {
      // The account email is the ACME contact. This is what turns Let's
      // Encrypt's expiry warnings back on; without it a certificate that stops
      // renewing is only discovered by a visitor.
      acmeEmail = user.email ?? null;
      const resolved = await resolveCloudflareToken(user);
      if (resolved.token) {
        cloudflareToken = resolved.token;
        notes.push("your connected Cloudflare account is available, so wildcard certificates can be issued automatically (DNS-01)");
      } else {
        notes.push(
          "Cloudflare is not connected, so a wildcard certificate (needed when an app gives each tenant its own subdomain) cannot be issued automatically — connect it in Settings and we can finish that for you"
        );
      }
    }
  } catch (e) {
    // A DB hiccup here must never fail a migration — it only costs a rung.
    console.error("[migrate] could not resolve Cloudflare/ACME inputs", e);
    notes.push("we could not read your Cloudflare connection just now, so certificates were issued without it");
  }

  try {
    const domains = await db.domain.findMany({
      where: { userId },
      select: { name: true },
      orderBy: { name: "asc" },
      take: 50,
    });
    for (const d of domains) if (d.name) knownDomains.push(d.name);
  } catch (e) {
    console.error("[migrate] could not load registered domains", e);
  }

  return { cloudflareToken, acmeEmail, knownDomains, note: notes.join("; ") };
}

/**
 * POST-DNS-CUTOVER certificate pass.
 *
 * HTTP-01 cannot validate a hostname that still resolves to the OLD server —
 * that is a property of the protocol, not a bug — so at migration time every
 * name whose DNS has not moved comes back as a named pending item. This is the
 * second half: run the same ladder again once the record is live.
 *
 * `issueMigrationCertificates` was written for exactly this and, until now, had
 * ZERO callers, so TLS was never retried after cutover and the customer's first
 * HTTPS visit was a certificate warning.
 *
 * Deliberate properties:
 *   - It copies NOTHING. It re-reads the `sites.json` the original run persisted
 *     on the target, walks the ladder, and reloads the vhost. A migration is
 *     never re-run by this path, so an accidental/duplicate enqueue cannot
 *     re-transfer a customer's data over the top of itself.
 *   - It is idempotent: certbot's `--keep-until-expiring` makes it a no-op once
 *     a certificate is in place, so it is safe to enqueue repeatedly.
 *   - It does NOT touch `Migration.status`. The terminal outcome belongs to the
 *     run that measured it; a certificate pass has not re-probed the sites and
 *     must not silently upgrade `COMPLETED_WITH_ISSUES` to `DONE`.
 *   - It never touches the SOURCE server.
 *
 * Enqueue it with:
 *   db.job.create({ data: { type: "MIGRATE", payload: { migrationId, phase: "tls" } } })
 */
async function runPostCutoverTls(
  migration: Awaited<ReturnType<typeof loadMigration>>,
  items: MigrationItems
): Promise<void> {
  const target = migration.server;
  const targetName = target ? target.label || target.hostname : "your server";

  // Append-only log write: the migration row is already terminal and its status,
  // progress and step are the honest record of the run that produced them.
  let log = migration.log ?? null;
  const say = async (line: string) => {
    log = appendLog(log, line);
    await db.migration.update({ where: { id: migration.id }, data: { log } }).catch(() => {});
  };

  if (!REAL_MIGRATION) {
    await say("HTTPS re-check skipped: real migration is not enabled on this platform, so no certificate was requested.");
    return;
  }

  await say("Your DNS has moved — re-checking HTTPS and issuing any certificate that could not be issued before.");
  const tls = await resolveTlsInputs(migration.userId);
  if (tls.note) await say(`  ${tls.note}.`);

  const res = await issueMigrationCertificates({
    target: target as any,
    migrationId: migration.id,
    extraDomains: tls.knownDomains,
    cloudflareToken: tls.cloudflareToken,
    acmeEmail: tls.acmeEmail,
    // Progress is meaningless for a post-cutover pass (the migration is over), so
    // the reporter is used purely as a log sink.
    report: async (_p, _s, line) => {
      await say(line);
    },
  });

  if (res.error) {
    await say(`HTTPS re-check could not run: ${res.error}`);
    await notify(
      migration.userId,
      `Couldn't finish HTTPS on ${targetName}`,
      `${res.error} Your site keeps serving; only the certificate step is outstanding. Nothing on your old server was touched.`,
      "/dashboard/migrate"
    );
    return;
  }

  const secured = res.secured ?? [];
  const pending = res.pending ?? [];
  if (secured.length) {
    await say(`HTTPS is live for ${secured.slice(0, 8).join(", ")}${secured.length > 8 ? ` (+${secured.length - 8} more)` : ""}.`);
  }
  for (const p of pending.slice(0, 8)) await say(`  HTTPS still outstanding for ${p.domain}: ${p.why}. To finish: ${p.fix}`);

  await notify(
    migration.userId,
    pending.length
      ? `HTTPS on ${targetName} — ${secured.length} secured, ${pending.length} still to finish`
      : `HTTPS is live on ${targetName}`,
    (secured.length ? `A valid certificate is now in place for ${secured.slice(0, 6).join(", ")}. ` : "") +
      (pending.length
        ? `Still outstanding: ${pending.slice(0, 4).map((p) => `${p.domain} — ${p.why}`).join(" | ")}. `
        : "") +
      // Said every time, because it is the customer's actual safety net and the
      // moment DNS has just moved is the moment they most need to know it.
      "Your old server was only ever read from — nothing on it was changed, so pointing DNS back to it is still a complete rollback.",
    "/dashboard/migrate"
  );
}

